1	import nodemailer from "nodemailer";
2	import { db } from "./db";
3	import { decryptSecret } from "./crypto-box";
4	import { mayDeliverTo, type NotifyKind } from "./prefs";
5	import {
6	  renderTemplate,
7	  recordEmail,
8	  wrapEmail,
9	  emailButton,
10	  appUrl,
11	  emailHeading,
12	  emailParagraph,
13	  emailEyebrow,
14	  emailNote,
15	  emailPanel,
16	  emailBanner,
17	  emailKeyValue,
18	  type Accent,
19	} from "./email-render";
20	import { invoiceBranding } from "./invoices";
21	import { renderInvoicePDF, invoicePdfFilename } from "./invoice-pdf";
22	import { emails as catalogEmails, type BuiltEmail } from "./email-templates";
23	
24	/**
25	 * SMTP config comes from the Setting table (admin-editable) with env fallback.
26	 * Keys: smtp_host, smtp_port, smtp_user, smtp_pass, smtp_from, smtp_secure.
27	 * If nothing is configured, falls back to a local sendmail/Postfix relay on :25.
28	 */
29	/**
30	 * The stored SMTP password, decrypted — tolerating a LEGACY plaintext row.
31	 *
32	 * `smtp_pass` is now written through `encryptSecret` (iv:tag:ciphertext), but a
33	 * value saved before that change is bare plaintext. `decryptSecret` returns null
34	 * on a value that is not in the encrypted shape, so a null result means "this was
35	 * never encrypted" — fall back to the raw stored value. Once an operator re-saves
36	 * the SMTP settings, the row is encrypted and this fallback stops being taken.
37	 */
38	function smtpPassPlain(stored: string | undefined): string {
39	  if (!stored) return "";
40	  const dec = decryptSecret(stored);
41	  return dec ?? stored;
42	}
43	
44	async function loadSmtp() {
45	  const rows = await db.setting.findMany({
46	    where: { key: { in: ["smtp_host", "smtp_port", "smtp_user", "smtp_pass", "smtp_from", "smtp_secure"] } },
47	  });
48	  const s = Object.fromEntries(rows.map((r) => [r.key, r.value]));
49	  const host = s.smtp_host || process.env.SMTP_HOST || "";
50	  const from = s.smtp_from || process.env.SMTP_FROM || `Nxeon <no-reply@${(process.env.APP_URL ?? "localhost").replace(/^https?:\/\//, "")}>`;
51	  return {
52	    host,
53	    port: Number(s.smtp_port || process.env.SMTP_PORT || 587),
54	    user: s.smtp_user || process.env.SMTP_USER || "",
55	    pass: smtpPassPlain(s.smtp_pass) || process.env.SMTP_PASS || "",
56	    secure: (s.smtp_secure ?? process.env.SMTP_SECURE) === "true",
57	    from,
58	  };
59	}
60	
61	export async function mailConfigured(): Promise<boolean> {
62	  const c = await loadSmtp();
63	  return !!c.host || process.env.NXEON_LOCAL_MAIL === "1";
64	}
65	
66	function transport(c: Awaited<ReturnType<typeof loadSmtp>>) {
67	  if (!c.host) {
68	    // Local MTA fallback (Postfix/sendmail on the host)
69	    return nodemailer.createTransport({ sendmail: true, newline: "unix", path: "/usr/sbin/sendmail" });
70	  }
71	  // When the SMTP host is an internal IP (e.g. the mail VM at 10.20.0.10) but the
72	  // server presents a cert for its hostname (mail.nxeon.cloud), TLS validation
73	  // fails on an IP mismatch. `SMTP_TLS_SERVERNAME` lets us keep cert verification
74	  // on while telling TLS the name to validate against (and sets SNI accordingly).
75	  const servername = process.env.SMTP_TLS_SERVERNAME || undefined;
76	  return nodemailer.createTransport({
77	    host: c.host,
78	    port: c.port,
79	    secure: c.secure,
80	    auth: c.user ? { user: c.user, pass: c.pass } : undefined,
81	    ...(servername ? { tls: { servername } } : {}),
82	  });
83	}
