159	/**
160	 * Staff reply carrying an image attachment. Same authorization and side effects
161	 * as `replyToConversation` (requireArea("support"), notify, assign, unread) but
162	 * the message body may be empty and it stores a signature-verified image in
163	 * Postgres. All security checks (allow-list, magic-number, 5 MB cap, SVG
164	 * rejection) run in `validateImageBytes` — the client cannot bypass them.
165	 */
166	export async function replyWithAttachment(
167	  formData: FormData
168	): Promise<{ error?: string; ok?: boolean }> {
169	  const staff = await requireArea("support");
170	
171	  // Throttle staff uploads defensively (shared limiter, keyed by staff id).
172	  const rl = checkRateLimit(`chat-upload:${staff.id}`, { max: 30, windowMs: 60_000 });
173	  if (!rl.ok) return { error: "Too many uploads. Please slow down." };
174	
175	  const id = formData.get("conversationId");
176	  const rawBody = formData.get("body");
177	  const file = formData.get("file");
178	
179	  if (typeof id !== "string" || !id) return { error: "Invalid conversation." };
180	  const body = typeof rawBody === "string" ? rawBody.trim().slice(0, 5000) : "";
181	  if (!(file instanceof File)) return { error: "No image provided." };
182	  if (file.size > 5 * 1024 * 1024) return { error: "Image is larger than 5 MB." };
183	
184	  const convo = await db.chatConversation.findUnique({ where: { id } });
185	  if (!convo) return { error: "Conversation not found." };
186	
187	  const bytes = Buffer.from(await file.arrayBuffer());
188	  const check = validateImageBytes(bytes, file.type);
189	  if (!check.ok) return { error: check.error };
190	
191	  await db.$transaction(async (tx) => {
192	    const msg = await tx.chatMessage.create({
193	      data: { conversationId: id, sender: "agent", body },
194	    });
195	    await tx.chatAttachment.create({
196	      data: {
197	        messageId: msg.id,
198	        mime: check.mime,
199	        sizeBytes: check.bytes.length,
200	        data: new Uint8Array(check.bytes),
201	      },
202	    });
203	    await tx.chatConversation.update({
204	      where: { id },
205	      data: {
206	        status: "OPEN",
207	        unreadForUser: true,
208	        unreadForAgent: false,
209	        assignedToId: staff.id,
210	        lastMessageAt: new Date(),
211	      },
212	    });
213	  });
214	
215	  if (convo.userId) {
216	    await db.notification
217	      .create({
218	        data: {
219	          userId: convo.userId,
220	          title: "New reply in your live chat",
221	          href: "/dashboard",
222	        },
223	      })
224	      .catch(() => {});
225	  }
226	
227	  revalidatePath("/admin/chat");
228	  return { ok: true };
229	}
