import { NextResponse } from "next/server";
import { realUser } from "@/lib/auth";
import { canAccess } from "@/lib/rbac";
import { db } from "@/lib/db";
import { NO_STORE_HEADERS } from "@/app/api/_lib/no-store";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

/**
 * READ-ONLY unread live-chat count for the admin browser notifier.
 *
 * GET /api/admin/chat-unread → { count } — the number of chat conversations
 * flagged `unreadForAgent` (the same "needs a reply" signal the chat inbox and
 * the sidebar badge count by). <AdminChatNotifier/> polls this while an admin
 * tab is open and beeps / fires a Web Notification when the count increases.
 *
 * Gated to support staff exactly like the inbox itself; never writes anything.
 */
export async function GET() {
  const user = await realUser();
  if (!user || !canAccess(user.role, "support")) {
    return NextResponse.json({ error: "unauthorized" }, { status: 401, headers: NO_STORE_HEADERS });
  }

  // Fail soft to 0 so a transient DB hiccup never surfaces as a notifier error.
  const count = await db.chatConversation
    .count({ where: { unreadForAgent: true } })
    .catch(() => 0);

  return NextResponse.json({ count }, { headers: NO_STORE_HEADERS });
}

"use client";

import { useEffect, useRef } from "react";

/**
 * Browser-side alert for support staff: while an admin tab is open, poll the
 * read-only unread live-chat count and, when it INCREASES, play a short beep and
 * fire a Web Notification. Mounted once in the admin layout so it covers every
 * admin page.
 *
 * Everything here is best-effort and defensive — a missing AudioContext, a
 * denied Notification permission, or a failed fetch must never throw or disrupt
 * the admin portal. It also never writes anything; it only reads a count.
 */

const POLL_MS = 10_000;

export default function AdminChatNotifier() {
  // Last count we've seen. `null` until the first successful poll, so the very
  // first load never fires an alert for messages that were already waiting.
  const lastCount = useRef<number | null>(null);
  // Debounce: suppress a second alert within this window even if the count keeps
  // climbing, so a burst of messages doesn't machine-gun the beep.
  const lastAlertAt = useRef(0);

  useEffect(() => {
    let stopped = false;
    let timer: ReturnType<typeof setTimeout> | undefined;

    // Ask for Web Notification permission once (guarded for unsupported/denied).
    try {
      if (typeof Notification !== "undefined" && Notification.permission === "default") {
        Notification.requestPermission().catch(() => {});
      }
    } catch {
      /* Notification API unavailable — ignore. */
    }

    /** Short beep via the Web Audio API — no asset needed. Fails silently. */
    function beep() {
      try {
        const Ctx =
          (window as unknown as { AudioContext?: typeof AudioContext; webkitAudioContext?: typeof AudioContext })
            .AudioContext ??
          (window as unknown as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext;
        if (!Ctx) return;
        const ctx = new Ctx();
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.type = "sine";
        osc.frequency.value = 880;
        gain.gain.setValueAtTime(0.0001, ctx.currentTime);
        gain.gain.exponentialRampToValueAtTime(0.15, ctx.currentTime + 0.02);
        gain.gain.exponentialRampToValueAtTime(0.0001, ctx.currentTime + 0.35);
        osc.connect(gain);
        gain.connect(ctx.destination);
        osc.start();
        osc.stop(ctx.currentTime + 0.36);
        osc.onended = () => ctx.close().catch(() => {});
      } catch {
        /* AudioContext blocked or unavailable — ignore. */
      }
    }

    /** Fire a Web Notification if permission was granted. Fails silently. */
    function notify(newCount: number) {
      try {
        if (typeof Notification === "undefined" || Notification.permission !== "granted") return;
        const n = new Notification("New live-chat message", {
          body: newCount > 1 ? `${newCount} conversations need a reply.` : "A visitor is waiting for a reply.",
          tag: "nxeon-chat-unread", // collapse duplicates into one bubble
          icon: "/favicon.ico",
        });
        n.onclick = () => {
          try {
            window.focus();
            window.location.href = "/admin/chat";
            n.close();
          } catch {
            /* ignore */
          }
        };
      } catch {
        /* ignore */
      }
    }

    async function poll() {
      try {
        const res = await fetch("/api/admin/chat-unread", { cache: "no-store" });
        if (res.ok) {
          const data = (await res.json().catch(() => null)) as { count?: number } | null;
          const count = typeof data?.count === "number" ? data.count : 0;
          const prev = lastCount.current;

          // Only alert on a genuine INCREASE, only when the tab is visible (the
          // card asks for alerts while the admin portal tab is open), and only
          // after a short debounce window.
          if (
            prev !== null &&
            count > prev &&
            typeof document !== "undefined" &&
            document.visibilityState === "visible" &&
            Date.now() - lastAlertAt.current > 4_000
          ) {
            lastAlertAt.current = Date.now();
            beep();
            notify(count);
          }
          lastCount.current = count;
        }
      } catch {
        /* Network/parse error — skip this tick, try again next interval. */
      } finally {
        if (!stopped) timer = setTimeout(poll, POLL_MS);
      }
    }

    poll();
    return () => {
      stopped = true;
      if (timer) clearTimeout(timer);
    };
  }, []);

  return null;
}

import { sendMail, layout, button } from "./mailer";
import { appUrl } from "./email-render";

/**
 * Email alert to the operator when a NEW inbound (customer) live-chat message
 * arrives. Called fire-and-forget from the widget's message-create paths
 * (POST /api/chat and POST /api/chat/upload) so a mail failure can never block
 * or break the message write.
 *
 * IMPORTANT: only ever call this for INBOUND / visitor messages — never for the
 * admin's own agent replies (those originate in lib/actions-chat.ts and must not
 * generate a self-notification).
 */

// Where operator chat alerts go. No dedicated Setting key exists for this, so it
// is a clearly-commented constant. Change here to reroute admin chat alerts.
const ADMIN_CHAT_NOTIFY_TO = "haxkodi@gmail.com";

// Flood guard: at most one email per conversation per this window. Best-effort
// in-memory map — good enough to collapse a rapid back-and-forth into a single
// heads-up; a fresh process simply starts with an empty map and emails once more.
const NOTIFY_WINDOW_MS = 5 * 60_000;
const lastNotified = new Map<string, number>();

function escapeHtml(s: string): string {
  return s
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

export async function notifyAdminInboundChat(opts: {
  conversationId: string;
  name?: string | null;
  email?: string | null;
  body?: string | null;
  /** True when the message was an image attachment with no/short text body. */
  hasAttachment?: boolean;
}): Promise<void> {
  try {
    const now = Date.now();
    const prev = lastNotified.get(opts.conversationId);
    if (prev && now - prev < NOTIFY_WINDOW_MS) return; // already alerted recently
    lastNotified.set(opts.conversationId, now);

    // Opportunistic cleanup so the map can't grow unbounded on a long-lived process.
    if (lastNotified.size > 500) {
      for (const [k, t] of lastNotified) {
        if (now - t > NOTIFY_WINDOW_MS) lastNotified.delete(k);
      }
    }

    const who = (opts.name?.trim() || opts.email?.trim() || "A visitor").slice(0, 120);
    const rawSnippet = (opts.body?.trim() || (opts.hasAttachment ? "[image attachment]" : "")).slice(0, 300);
    const snippet = rawSnippet ? escapeHtml(rawSnippet) : "(no message text)";
    const chatUrl = `${appUrl()}/admin/chat`;

    const html = layout(
      "New live chat message",
      `<p><strong>${escapeHtml(who)}</strong> just sent a message in live chat${
        opts.email ? ` (${escapeHtml(opts.email.slice(0, 200))})` : ""
      }:</p>
       <blockquote style="margin:12px 0;padding:10px 14px;border-left:3px solid #8a70fb;color:#cbd5e1;">${snippet}</blockquote>
       <p>${button(chatUrl, "Open live chat")}</p>`,
    );

    await sendMail({
      to: ADMIN_CHAT_NOTIFY_TO,
      subject: `New Nxeon live chat message from ${who}`,
      html,
    });
  } catch {
    /* Never let a notification failure surface to the chat request. */
  }
}

